// Turn Grafana's firing `tool093-reviewer-failed` alerts into one item per pull request.
//
// Grafana's stock webhook body is `{status, alerts: [{status, labels, startsAt, ruleUID, ...}]}`,
// one entry per alert instance in the group, and `labels.pr` is the URL PR-Agent was working on
// (`sum by (pr)` in the rule). A group is re-sent whole when another PR joins it, so an alert
// can arrive again with the same `startsAt`: the marker below is how a repeat is recognised.
//
// Everything that reaches a Gitea URL below was matched against a strict pattern first. The
// bearer already limits callers to Grafana; this keeps a label that is not a pull request of
// THIS forge from ever becoming a request path. (The task runner's sandbox has no `URL`, hence
// the pattern rather than a parsed origin.)
const ORIGIN = 'https://RESOLVE_GITEA_DOMAIN';
const RULE_UID = 'tool093-reviewer-failed';
const STARTS_AT = /^\d{4}-\d{2}-\d{2}T[\d:.]+Z$/;
const PR_URL = /^(https?:\/\/[A-Za-z0-9.:-]+)\/([A-Za-z0-9._-]+)\/([A-Za-z0-9._-]+)\/pulls\/(\d+)$/;

const body = $json.body ?? {};
const out = [];
for (const alert of Array.isArray(body.alerts) ? body.alerts : []) {
  if (alert.status !== 'firing' || alert.ruleUID !== RULE_UID) continue;
  if (!STARTS_AT.test(String(alert.startsAt ?? ''))) continue;
  const m = String(alert.labels?.pr ?? '').match(PR_URL);
  if (!m || m[1].toLowerCase() !== ORIGIN) continue;
  if (/^\.+$/.test(m[2]) || /^\.+$/.test(m[3])) continue;  // `..` is a path segment, not a name
  out.push({
    json: {
      origin: ORIGIN,
      owner: m[2],
      repo: m[3],
      index: m[4],
      marker: `<!-- forge-review-failed:${alert.startsAt} -->`,
      since: alert.startsAt,
    },
  });
}
// A webhook answers with its last node's items, and none at all is a 500 that Grafana would retry
// as a failed notification. Nothing to comment on still has to be a clean, empty answer.
return out.length ? out : [{ json: { skip: true } }];

// Say it once per failure: comment only if no comment on the PR carries this alert's marker.
// Only comments updated since the alert began are listed (`since`): the marker of THIS failure can
// only be in one of those, and it keeps a long thread from pushing it onto a second page.
//
// The GET runs with `fullResponse`, so its output is ONE item per pull request whose `body` is the
// whole comment list. Without it an HTTP node emits one item per array element (nothing at all for
// a PR with no comments, which would end the run before the first notice is ever posted).
const res = $input.item.json;
const pr = $('Parse Alerts').item.json;
const comments = Array.isArray(res.body) ? res.body : null;
if (comments === null) {
  throw new Error(`could not read the comments of ${pr.owner}/${pr.repo}#${pr.index} (status ${res.statusCode})`);
}
const already = comments.some((c) => typeof c.body === 'string' && c.body.includes(pr.marker));
const comment = [
  '**The automated review did not run for this pull request.**',
  '',
  'The reviewer failed on every model it tried, so no review will be posted here on its own. ' +
    'Push a commit to retry; a `/review` comment is ignored.',
  '',
  'The operator has been alerted.',
  '',
  pr.marker,
].join('\n');
return { json: { ...pr, post: !already, comment } };

// Answer Grafana with a fixed acknowledgement. A webhook returns its last node's items, and
// Post Comment's are Gitea's comment JSON, user object included.
return $input.all().map(() => ({ json: { posted: true } }));
